insert into public.balanceamento (nome, versao, dados, ativa, publico) values
	('acessibilidade', 1, $json${"versao":1,"_nota":"Acessibilidade (GDD O que acrescentar; Pacote 3.24): tamanho do texto (multiplica o tamanho de cada texto da interface), idiomas oferecidos ('' = o do aparelho) e os padroes das opcoes salvas em estado.config. economia_bateria: ver \"bateria\".","tamanhos_texto":{"pequeno":0.85,"normal":1.0,"grande":1.2,"muito_grande":1.4},"ordem_tamanhos":["pequeno","normal","grande","muito_grande"],"idiomas":["","pt_BR","en"],"padrao":{"canhoto":false,"vibracao":true,"texto":"normal","idioma":"","economia_bateria":false,"privacidade_aceita":0,"anuncios_personalizados":false,"volume_musica":100,"volume_sfx":100,"volume_voz":100,"volume_ambiente":100,"volume_ui":100},"bateria":{"_nota":"Modo economia de bateria (3.25): limita os quadros por segundo e reduz as particulas (chuva da vila, faiscas, lascas, flamulas da torcida) a particulas_pct.","fps_normal":60,"fps_economia":30,"particulas_pct":40}}$json$::jsonb, true, true),
	('chat_rapido', 1, $json${"versao":1,"_nota":"Mensagens rapidas (botoes do chat) e falas dos membros simulados. Cada id vira o texto MSG_<ID> em game/i18n/textos.csv (pt_BR e en). Acrescente aqui e la.","rapidas":["boa_justa","revanche","obrigado","ajuda_por_favor","parabens","boa_sorte","vamos_ordem","ate_logo"],"simuladas_ordem":["boa_justa","parabens","vamos_ordem","ajuda_por_favor","obrigado","torneio_semana","novo_membro"],"simuladas_global":["boa_justa","revanche","boa_sorte","procuro_ordem","parabens","ate_logo"]}$json$::jsonb, true, true),
	('desgaste', 1, $json${"versao":1,"_nota":"Desgaste e conserto (GDD: toda peca se desgasta com os impactos; com durabilidade zero perde os bonus ate ser consertada; conserto custa ouro e um pouco de material, proporcional ao dano, e peca quebrada custa mais). estagios: % de durabilidade abaixo da qual a peca muda de aparencia (d1 riscada, d2 amassada, d3 rachada). Tempo de conserto pelo nivel do cavaleiro (GDD Timers: niveis 1-5 de 1 a 3 min, 6-10 de 5 a 15, 11-20 de 15 a 30, 21+ de 30 a 60).","estagios_pct":[75,50,25],"conserto":{"ouro_por_ponto_milesimos":500,"material":"sucata","pontos_por_material":20,"quebrada_custo_pct":150,"segundos_por_nivel":[[1,60],[3,120],[5,180],[6,300],[8,600],[10,900],[11,900],[15,1200],[20,1800],[21,1800],[30,3600]],"vagas":{"base":1,"extra_no_nivel_do_predio":3}}}$json$::jsonb, true, true),
	('economia', 1, $json${"versao":1,"_nota":"Parametros da economia usados pela simulacao (tools/simular_economia.gd, prompt 3.12) e pelos sistemas da Parte 3 (baus 3.14, forja 3.15, ligas 3.17, loja/VIP/passe 3.18, anuncios 3.19, missoes 3.21). Os sistemas leem DAQUI; ajuste os numeros e rode a simulacao de novo. Poder = media dos atributos do cavaleiro e do cavalo / 2 + soma do poder das 6 pecas.","perfis":{"gratis":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":0,"vip":false,"passe":false,"habilidade":0.0},"gratis_anuncios":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":5,"vip":false,"passe":false,"habilidade":0.0},"pagante":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":0,"vip":true,"passe":true,"habilidade":0.0},"gratis_habilidoso":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":0,"vip":false,"passe":false,"habilidade":0.15,"so_teste":true},"pagante_ruim":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":0,"vip":true,"passe":true,"habilidade":-0.15,"so_teste":true},"so_vip":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":0,"vip":true,"passe":false,"habilidade":0.0,"so_teste":true},"so_passe":{"minutos_dia":15,"sessoes_dia":2,"anuncios_dia":0,"vip":false,"passe":true,"habilidade":0.0,"so_teste":true}},"justa":{"minutos_por_justa":1.5,"prob_base":0.55,"prob_por_poder":0.02,"prob_min":0.05,"prob_max":0.95,"tres_estrelas_dada_vitoria":0.35,"justas_com_folego":4,"penalidade_cansado":0.08,"ouro_conserto_por_justa":6},"poder_raridade":{"comum":3,"incomum":5,"raro":8,"epico":12,"lendario":17},"poder_por_melhoria":1,"espacos_conjunto":["elmo","peitoral","ombreiras","escudo","lanca","caparacao"],"conjuntos":[{"nome":"escudeiro","raridade":"comum"},{"nome":"vigia","raridade":"incomum"},{"nome":"cavaleiro_andante","raridade":"incomum"},{"nome":"ferro_negro","raridade":"raro"},{"nome":"guarda_real","raridade":"raro"},{"nome":"dragao","raridade":"epico"},{"nome":"rei_sol","raridade":"lendario"}],"regioes":[{"nome":"feiras","ouro_torneio":60,"xp_torneio":40,"torneios":5,"disputas":4,"nivel_minimo":2,"poder_inicial":32,"poder_final":66,"ouro_vitoria":16,"xp_vitoria":14,"projeto_campeao":"vigia"},{"nome":"condado","ouro_torneio":110,"xp_torneio":70,"torneios":6,"disputas":4,"nivel_minimo":5,"poder_inicial":66,"poder_final":106,"ouro_vitoria":26,"xp_vitoria":22,"projeto_campeao":"ferro_negro"},{"nome":"ducado","ouro_torneio":170,"xp_torneio":110,"torneios":6,"disputas":5,"nivel_minimo":8,"poder_inicial":106,"poder_final":126,"ouro_vitoria":40,"xp_vitoria":32,"projeto_campeao":"guarda_real"},{"nome":"reino","ouro_torneio":260,"xp_torneio":160,"torneios":7,"disputas":5,"nivel_minimo":10,"poder_inicial":126,"poder_final":144,"ouro_vitoria":60,"xp_vitoria":45,"projeto_campeao":"dragao"},{"nome":"grande_torneio","ouro_torneio":380,"xp_torneio":230,"torneios":8,"disputas":5,"nivel_minimo":12,"poder_inicial":144,"poder_final":160,"ouro_vitoria":90,"xp_vitoria":60,"projeto_campeao":"rei_sol"}],"ligas":{"nomes":["bronze","prata","ouro","platina","diamante","campeao"],"divisoes":["III","II","I"],"pontos_por_divisao":100,"vitoria":20,"derrota":-16,"defesa_vencida":4,"defesas_por_dia":3,"ouro_vitoria":14,"ouro_por_liga":8,"xp_vitoria":16,"recompensa_temporada":["ferro","ferro","ouro","ouro","real","real"],"_nota_local":"Ate o servidor (3.5/3.6): fantasmas, defesas, ranking e campeonato sao SIMULADOS no aparelho (marcados como simulados na tela).","fantasmas":{"perfil":"equilibrado","candidatos":12,"variacao_pontos":150},"campeonato":{"dias_semana":[6,0],"rodadas":3,"premios":[{"ouro":40},{"ouro":100,"bau":"ferro"},{"ouro":250,"bau":"ouro"}]},"ranking_simulado":20,"poder_rival_base":40,"poder_rival_por_ponto":0.1,"faixa_poder":15,"temporada_dias":28,"reinicio_pct":50},"baus":{"espacos":4,"tipos":{"madeira":{"segundos":300,"ouro":[20,40],"itens":1,"fragmentos":[1,2],"raridade":{"comum":75,"incomum":22,"raro":3}},"ferro":{"segundos":3600,"ouro":[60,100],"itens":2,"fragmentos":[2,4],"raridade":{"comum":40,"incomum":40,"raro":17,"epico":3}},"ouro":{"segundos":14400,"ouro":[150,250],"itens":3,"fragmentos":[4,7],"raridade":{"incomum":45,"raro":40,"epico":13,"lendario":2}},"real":{"segundos":43200,"ouro":[400,600],"itens":4,"fragmentos":[8,12],"raridade":{"raro":55,"epico":37,"lendario":8}}},"chance_madeira_por_vitoria":0.5,"ferro_por_tres_estrelas":true,"ouro_por_campeao":true,"garantia_raro_a_cada":10,"garantia_conta":["ferro","ouro","real"],"_nota_cheio":"Vitoria com os 4 espacos cheios da so ouro (GDD): o minimo de ouro do bau que viria.","fragmentos_por_repetida":4},"melhoria":{"nivel_max":10,"garantido_ate":5,"teto_por_nivel_armeiro":2,"chance_sucesso_pct":[100,100,100,100,100,80,65,50,35,25],"custo_fragmentos":[10,15,22,32,45,65,90,125,170,230],"custo_ouro":[45,75,120,180,270,390,540,750,1050,1400],"custo_lingotes":[0,0,1,1,2,2,3,4,5,6]},"forja":{"_nota":"Forja (GDD Forja, 3.15). Ferreiro: funde lingote_por_sucata sucatas em 1 lingote de ferro e aco_por_ferro lingotes de ferro em 1 de aco, fundir_segundos_por_lingote cada (fila propria, vagas_fundicao). Armeiro: cria a peca de um conjunto cujo projeto o jogador tem, com a receita da raridade do conjunto (materiais, ouro, tempo; fila vagas_forja) e variacao de +-variacao_status_pct em cada status. Cada nivel de melhoria soma bonus_status_por_nivel_pct do status base. sucata_por_vitoria e so da simulacao (no jogo vem de pve.json > regioes > materiais_vitoria).","lingote_por_sucata":4,"aco_por_ferro":3,"fundir_segundos_por_lingote":60,"vagas_fundicao":1,"vagas_forja":{"base":1,"extra_no_nivel_do_predio":5},"sucata_por_vitoria":2,"receitas":{"comum":{"materiais":{"lingote_ferro":3},"ouro":40,"segundos":600},"incomum":{"materiais":{"lingote_ferro":8,"couro":2},"ouro":120,"segundos":3600},"raro":{"materiais":{"lingote_ferro":10,"lingote_aco":1,"couro":3},"ouro":300,"segundos":7200},"epico":{"materiais":{"lingote_aco":6,"couro":4,"tecido_nobre":2,"ornamento":1},"ouro":700,"segundos":14400},"lendario":{"materiais":{"lingote_aco":12,"tecido_nobre":4,"ornamento":3},"ouro":1500,"segundos":28800}},"variacao_status_pct":10,"bonus_status_por_nivel_pct":5},"vila_crescimento_poder":1,"vip":{"_nota":"vaga_treino_extra: a mesma vaga que o campo de treino libera (GDD: VIP da a 2a vaga, que o gratis ganha pelo nivel do predio); nao soma com ela.","timer_reducao_pct":20,"vaga_treino_extra":1,"folego_recuperacao_extra_pct":50,"beneficio_anuncios":true,"gemas_mes":150,"gemas_por_hora_bau":10},"passe":{"xp_por_justa":10,"xp_por_nivel":120,"niveis":30,"gratis":{"ouro_por_nivel":30,"bau_ferro_a_cada":6},"premium":{"ouro_por_nivel":50,"bau_ferro_a_cada":5,"bau_ouro_a_cada":15,"fragmentos_por_nivel":3,"projeto_nos_niveis":[15,30]}},"anuncios":{"limite_dia":5,"cortar_minutos":30,"dobrar_vitoria":2,"bau_madeira_extra":1},"missoes":{"ouro_dia":60,"fragmentos_dia":3,"chave_semana":1},"simulacao":{"_nota":"Comportamento do jogador simulado (tools/simular_economia.gd). Nao e balanceamento do jogo, e a estrategia do modelo.","dias":90,"sementes":40,"semente_base":7001,"limiar_pve":0.45,"reserva_ouro":40,"anuncios_uso":{"bau_madeira_extra":1,"dobrar_vitoria":2,"cortar_timer":2},"_nota_metas":"PROPOSTA (confirmar com o design): ritmo desejado (dia em que o marco chega). gratis = jogador gratis de 15 min/dia; pagante = VIP + passe. Ausente = nao precisa chegar em 90 dias. A simulacao compara as medianas com estas metas (tolerancia em %).","tolerancia_pct":25,"metas":{"gratis":{"regiao_condado":7,"regiao_ducado":25,"regiao_reino":50,"regiao_grande_torneio":80,"liga_prata":9,"liga_ouro":20,"liga_platina":45,"conjunto_incomum":15,"conjunto_raro":45,"nivel_10":25,"nivel_15":60},"pagante":{"regiao_condado":6,"regiao_ducado":18,"regiao_reino":38,"regiao_grande_torneio":60,"liga_prata":9,"liga_ouro":15,"liga_platina":35,"liga_diamante":60,"conjunto_incomum":10,"conjunto_raro":25,"nivel_10":22,"nivel_15":50}}}}$json$::jsonb, true, true),
	('galope', 1, $json${"versao":2,"largada":{"bandeira_ms":250,"bandeira_variacao_ms":350,"perfeita_ms":150,"boa_ms":350,"velocidade_inicial_pct":{"perfeita":115,"boa":100,"ruim":85},"bonus_precisao_pct":{"perfeita":10,"boa":0,"ruim":0}},"pista":{"distancia_total":1000,"distancia_mira":150},"galope":{"compasso_ms":500,"janela_base_ms":70,"janela_por_temperamento_milesimos":1000,"janela_max_ms":180,"velocidade_base":80,"velocidade_por_ponto_milesimos":300,"velocidade_min_pct":80,"velocidade_max_pct":120,"velocidade_max_cansado_pct":100,"ganho_pct":4,"perda_perdido_pct":4,"perda_sem_folego_pct":5},"folego":{"base":60,"por_ponto_milesimos":800,"custo_por_passada":10,"custo_erro":6}}$json$::jsonb, true, true),
	('historia', 1, $json${"versao":1,"_nota":"ENREDO PROVISORIO (Pacote 3.22: 'preencher quando o enredo estiver decidido'). Estrutura pronta: troque falas em game/i18n/textos.csv (HIST_*), personagens e condicoes aqui. Cena: quando = {evento: n} dos contadores de metas (ex.: regiao_vencida 1 = venceu as feiras); falas = [{quem, texto (chave i18n), expressao}]; quem = id de personagens ou 'jogador'. Companheiro: entra quando a cena 'entra_na_cena' foi vista; bonus = {tipo: pct} (renome_pct: renome das disputas; fundicao_tempo_pct: tempo do forno do ferreiro, negativo = mais rapido; folego_recupera_pct: recuperacao do folego do cavalo). Retrato provisorio = quadro com a cor e a inicial; arte em game/art/sprites/retratos/{id}_{expressao}.png quando existir.","personagens":{"arauto":{"nome":"PERSONAGEM_ARAUTO","cor":"c9a227","inicial":"B"},"ferreira":{"nome":"PERSONAGEM_FERREIRA","cor":"a23a2a","inicial":"B"},"escudeiro":{"nome":"PERSONAGEM_ESCUDEIRO","cor":"3f6e3a","inicial":"T"},"nemesis":{"nome":"RIVAL_NEMESIS_CORVO","cor":"2a2a30","inicial":"C"},"rei":{"nome":"RIVAL_REI_SANCHO_JUSTADOR","cor":"d4a72c","inicial":"S"}},"companheiros":{"arauto":{"entra_na_cena":"comeco","bonus":{"renome_pct":20},"predio":"arena"},"ferreira":{"entra_na_cena":"fim_feiras","bonus":{"fundicao_tempo_pct":-25},"predio":"ferreiro"},"escudeiro":{"entra_na_cena":"fim_condado","bonus":{"folego_recupera_pct":20},"predio":"estabulo"}},"cenas":{"comeco":{"quando":{"vitoria":1},"falas":[{"quem":"arauto","texto":"HIST_COMECO_1","expressao":"alegre"},{"quem":"jogador","texto":"HIST_COMECO_2","expressao":"neutro"},{"quem":"nemesis","texto":"HIST_COMECO_3","expressao":"debochado"},{"quem":"arauto","texto":"HIST_COMECO_4","expressao":"serio"}]},"fim_feiras":{"quando":{"regiao_vencida":1},"falas":[{"quem":"arauto","texto":"HIST_FIM_FEIRAS_1","expressao":"alegre"},{"quem":"ferreira","texto":"HIST_FIM_FEIRAS_2","expressao":"neutro"},{"quem":"jogador","texto":"HIST_FIM_FEIRAS_3","expressao":"neutro"},{"quem":"nemesis","texto":"HIST_FIM_FEIRAS_4","expressao":"bravo"}]},"fim_condado":{"quando":{"regiao_vencida":2},"falas":[{"quem":"escudeiro","texto":"HIST_FIM_CONDADO_1","expressao":"timido"},{"quem":"jogador","texto":"HIST_FIM_CONDADO_2","expressao":"neutro"},{"quem":"ferreira","texto":"HIST_FIM_CONDADO_3","expressao":"alegre"},{"quem":"nemesis","texto":"HIST_FIM_CONDADO_4","expressao":"debochado"}]},"fim_ducado":{"quando":{"regiao_vencida":3},"falas":[{"quem":"arauto","texto":"HIST_FIM_DUCADO_1","expressao":"alegre"},{"quem":"nemesis","texto":"HIST_FIM_DUCADO_2","expressao":"bravo"},{"quem":"escudeiro","texto":"HIST_FIM_DUCADO_3","expressao":"serio"}]},"fim_reino":{"quando":{"regiao_vencida":4},"falas":[{"quem":"arauto","texto":"HIST_FIM_REINO_1","expressao":"serio"},{"quem":"rei","texto":"HIST_FIM_REINO_2","expressao":"neutro"},{"quem":"nemesis","texto":"HIST_FIM_REINO_3","expressao":"serio"},{"quem":"jogador","texto":"HIST_FIM_REINO_4","expressao":"neutro"}]},"fim_grande":{"quando":{"regiao_vencida":5},"falas":[{"quem":"rei","texto":"HIST_FIM_GRANDE_1","expressao":"alegre"},{"quem":"nemesis","texto":"HIST_FIM_GRANDE_2","expressao":"serio"},{"quem":"ferreira","texto":"HIST_FIM_GRANDE_3","expressao":"alegre"},{"quem":"arauto","texto":"HIST_FIM_GRANDE_4","expressao":"alegre"}]}},"ordem":["comeco","fim_feiras","fim_condado","fim_ducado","fim_reino","fim_grande"]}$json$::jsonb, true, true),
	('ia_rival', 1, $json${"versao":1,"_nota":"Perfis da IA do rival. Tempos em ms, erros de mira em px do quadro do alvo, chances em milesimos. 'acelera': 'cedo' = toca todas as batidas ate metade_batidas e depois uma sim, uma nao; 'tarde' = o contrario. habilidade_batida: batida da corrida em que aciona a habilidade ativa (0 = nunca). deslocamento_mira_px: [x, y] somado ao centro da zona (o centro do peito fica atras do escudo pequeno do ombro; a parte livre e a frente do tronco).","perfis":{"novato":{"reacao_media_ms":320,"reacao_variacao_ms":220,"desvio_medio_ms":40,"desvio_variacao_ms":170,"perder_batida_milesimos":300,"acelera":"tarde","metade_batidas":4,"zona_preferida":"peito","erro_mira_px":20,"habilidade_batida":6,"deslocamento_mira_px":[0,0]},"equilibrado":{"reacao_media_ms":190,"reacao_variacao_ms":110,"desvio_medio_ms":0,"desvio_variacao_ms":90,"perder_batida_milesimos":120,"acelera":"cedo","metade_batidas":5,"zona_preferida":"peito","erro_mira_px":9,"habilidade_batida":4,"deslocamento_mira_px":[9,0]},"agressivo":{"reacao_media_ms":120,"reacao_variacao_ms":90,"desvio_medio_ms":-10,"desvio_variacao_ms":70,"perder_batida_milesimos":60,"acelera":"cedo","metade_batidas":7,"zona_preferida":"capacete","erro_mira_px":8,"habilidade_batida":2,"deslocamento_mira_px":[0,0]}}}$json$::jsonb, true, true),
	('impacto', 1, $json${"versao":2,"_nota":"Chances em milesimos (1000 = 100%). Teto suave: ate joelho_pct do teto o valor passa inteiro; acima, cada ponto rende menos e nunca passa do teto (GDD: perto do teto cada ponto rende menos). habilidade_carga_ms: tempo de Corrida ate a habilidade ativa poder ser acionada (GDD: carrega durante a corrida). v2 (3.16): habilidade tem grupo (ofensiva = ativa, botao que carrega; defensiva = passiva, dispara no impacto), familia (investida, bloqueio ou golpe_pesado: o ciclo vale pela familia) e vence (a familia que ela anula). As de conjunto (olhar_da_vigia, carga_andante, ...) sao versoes melhores de uma familia. GDD: nenhuma chega a 100% (bloqueio no maximo 70%, ativas uma vez por justa).","pontos":{"capacete":3,"peito":2,"escudo":1,"cavalo":0,"erro":0},"falta":{"zona":"cavalo","penalidade_pontos":2,"faltas_para_desclassificar":2},"teto_suave_joelho_pct":70,"bloqueio":{"zonas":["capacete","peito"],"vira_zona":"escudo","base_milesimos":50,"teto_milesimos":400},"derrubada":{"base_por_zona_milesimos":{"capacete":120,"peito":90,"escudo":30},"forca_menos_equilibrio_milesimos":3,"velocidade_por_pct_milesimos":4,"ritmo_max_milesimos":40,"poder_lanca_milesimos":2,"defesa_peca_milesimos":2,"teto_milesimos":450},"dano":{"base_por_zona":{"capacete":20,"peito":15,"escudo":10,"cavalo":8},"peca_por_zona":{"capacete":"elmo","peito":"peitoral","escudo":"escudo","cavalo":"peitoral_cavalo"},"velocidade_por_pct_milesimos":10,"defesa_reduz_por_ponto_milesimos":500,"minimo":1,"lanca_por_contato":4},"habilidades":{"investida":{"tipo":"ativa","grupo":"ofensiva","familia":"investida","vence":"bloqueio","derrubada_bonus_milesimos":80,"dano_bonus_pct":0,"bloqueio_milesimos":0},"golpe_pesado":{"tipo":"ativa","grupo":"ofensiva","familia":"golpe_pesado","vence":"investida","derrubada_bonus_milesimos":40,"dano_bonus_pct":50,"bloqueio_milesimos":0},"bloqueio":{"tipo":"passiva","grupo":"defensiva","familia":"bloqueio","vence":"golpe_pesado","derrubada_bonus_milesimos":0,"dano_bonus_pct":0,"bloqueio_milesimos":600},"olhar_da_vigia":{"tipo":"passiva","grupo":"defensiva","familia":"bloqueio","vence":"golpe_pesado","derrubada_bonus_milesimos":0,"dano_bonus_pct":0,"bloqueio_milesimos":650},"carga_andante":{"tipo":"ativa","grupo":"ofensiva","familia":"investida","vence":"bloqueio","derrubada_bonus_milesimos":100,"dano_bonus_pct":10,"bloqueio_milesimos":0},"martelo_negro":{"tipo":"ativa","grupo":"ofensiva","familia":"golpe_pesado","vence":"investida","derrubada_bonus_milesimos":50,"dano_bonus_pct":65,"bloqueio_milesimos":0},"baluarte_real":{"tipo":"passiva","grupo":"defensiva","familia":"bloqueio","vence":"golpe_pesado","derrubada_bonus_milesimos":0,"dano_bonus_pct":0,"bloqueio_milesimos":700},"furia_do_dragao":{"tipo":"ativa","grupo":"ofensiva","familia":"golpe_pesado","vence":"investida","derrubada_bonus_milesimos":60,"dano_bonus_pct":80,"bloqueio_milesimos":0},"lanca_do_sol":{"tipo":"ativa","grupo":"ofensiva","familia":"investida","vence":"bloqueio","derrubada_bonus_milesimos":120,"dano_bonus_pct":20,"bloqueio_milesimos":0}},"habilidade_carga_ms":1000}$json$::jsonb, true, true),
	('inicio', 1, $json${"versao":2,"_nota":"Estado inicial de um jogador novo e o inicio do jogo (GDD Inicio do jogo). primeiro_dia: na primeira duracao_s desde a criacao, todo timer termina em no maximo timer_max_s. tutorial: recompensa (leva ao nivel 2, que abre a arena), peca do primeiro bau (ja equipada), rival fraco da primeira justa e os veteranos da justa de exibicao. semente_primeira_justa: a primeira justa jogada usa sempre a mesma semente (bandeira e sorteios previsiveis; 3.24).","ouro":100,"gemas":0,"chaves":1,"materiais":{"sucata":5,"lingote_ferro":0,"couro":0},"cavaleiro":{"nivel":1,"xp":0,"atributos":{"forca":30,"precisao":30,"equilibrio":30},"habilidade":"investida"},"cavalo":{"atributos":{"velocidade":40,"folego":40,"temperamento":40,"vinculo":0}},"itens":["elmo_escudeiro","peitoral_escudeiro","escudo_escudeiro","lanca_escudeiro","caparacao_escudeiro"],"equipar":["elmo_escudeiro","peitoral_escudeiro","escudo_escudeiro","lanca_escudeiro","caparacao_escudeiro"],"predios":{"casa_senhorial":1,"estabulo":1,"campo_treino":1,"ferreiro":1},"primeiro_dia":{"duracao_s":86400,"timer_max_s":15},"tutorial":{"xp":60,"ouro":50,"item_bau":"elmo_vigia","rival_primeira_justa":{"perfil":"novato","casa":["verde_floresta","branco_osso"],"brasao":"novato","cavaleiro":{"forca":10,"precisao":5,"equilibrio":15},"cavalo":{"velocidade":25,"folego":40,"temperamento":20},"equipamento":["peitoral_escudeiro","escudo_escudeiro","lanca_escudeiro"],"habilidade":""},"exibicao":{"perfil_azul":"equilibrado","perfil_vermelho":"agressivo","semente":1234},"semente_primeira_justa":2024}}$json$::jsonb, true, true),
	('itens', 1, $json${"versao":1,"_nota":"Catalogo de pecas. status usa as mesmas chaves da regra do impacto (defesa, bloqueio_milesimos, poder, precisao). visual = variante da arte em game/art/sprites/personagem (camadas.json: {espaco}_{visual}_{animacao}.png). espaco: elmo, peitoral, escudo, lanca, caparacao (os da regra) e os demais do GDD quando tiverem arte. Conjuntos acima do vigia (3.13) usam a arte do vigia ate ter arte propria.","raridades":["comum","incomum","raro","epico","lendario"],"conjuntos":{"_nota":"GDD Conjuntos: com 2 pecas equipadas do mesmo conjunto o cavaleiro ganha bonus_2 (atributos); com o conjunto completo (todas as pecas do conjunto no catalogo) libera a habilidade dele (impacto.json > habilidades).","escudeiro":{"bonus_2":{"equilibrio":2},"habilidade":""},"vigia":{"bonus_2":{"equilibrio":3},"habilidade":"olhar_da_vigia"},"cavaleiro_andante":{"bonus_2":{"forca":3},"habilidade":"carga_andante"},"ferro_negro":{"bonus_2":{"forca":4},"habilidade":"martelo_negro"},"guarda_real":{"bonus_2":{"equilibrio":4},"habilidade":"baluarte_real"},"dragao":{"bonus_2":{"forca":5},"habilidade":"furia_do_dragao"},"rei_sol":{"bonus_2":{"precisao":5},"habilidade":"lanca_do_sol"}},"cores_raridade":{"comum":"c9c2b6","incomum":"6fbf5a","raro":"4f8fe0","epico":"b062d8","lendario":"f0a830"},"cores_bau":{"madeira":"8a5a2b","ferro":"7d8590","ouro":"d4a72c","real":"8e2a3a"},"modelos":{"elmo_escudeiro":{"espaco":"elmo","raridade":"comum","conjunto":"escudeiro","visual":"escudeiro","durabilidade_max":180,"status":{"defesa":8}},"peitoral_escudeiro":{"espaco":"peitoral","raridade":"comum","conjunto":"escudeiro","visual":"escudeiro","durabilidade_max":180,"status":{"defesa":8}},"escudo_escudeiro":{"espaco":"escudo","raridade":"comum","conjunto":"escudeiro","visual":"escudeiro","durabilidade_max":180,"status":{"defesa":5,"bloqueio_milesimos":40}},"lanca_escudeiro":{"espaco":"lanca","raridade":"comum","conjunto":"escudeiro","visual":"escudeiro","durabilidade_max":120,"status":{