	('justa', 1, $json${"versao":2,"_nota":"fases_ms.corrida e o teto da Corrida; ela termina antes quando os cavaleiros chegam ao ponto da Mira (galope.json, pista)","passadas":3,"passadas_extras_max":1,"fases_ms":{"apresentacao":2000,"largada":1000,"corrida":6000,"mira":2000,"impacto":2000}}$json$::jsonb, true, true),
	('loja', 1, $json${"versao":1,"_nota":"Loja (GDD Monetizacao; Pacote 3.18). Precos em dinheiro sao so referencia: a cobranca real e a validacao do recibo sao da 3.7 (servidor). Ate la, compras com dinheiro passam por um provedor de TESTE que so funciona em build de depuracao. Compras com gemas (cosmeticos, materiais, pular timer) valem de verdade. VIP e passe usam os numeros de economia.json > vip e > passe. Ofertas: aparecem no gatilho (derrota_por_pouco, subiu_liga, projeto_sem_material), no maximo uma por gatilho a cada intervalo_s, e somem em duracao_s.","gemas":[{"id":"gemas_pequeno","gemas":80,"preco":"R$ 4,90"},{"id":"gemas_medio","gemas":450,"preco":"R$ 24,90"},{"id":"gemas_grande","gemas":1000,"preco":"R$ 49,90"}],"vip":{"id":"vip_mensal","dias":30,"preco":"R$ 19,90 por mês"},"passe":{"id":"passe_premium","preco":"R$ 14,90 por temporada"},"cosmeticos":[{"id":"frase_trovao","tipo":"frase_arauto","gemas":120},{"id":"frase_lenda","tipo":"frase_arauto","gemas":120},{"id":"frase_povo","tipo":"frase_arauto","gemas":80},{"id":"vitoria_dourada","tipo":"efeito_vitoria","cor":"f0c040","gemas":150},{"id":"vitoria_rubra","tipo":"efeito_vitoria","cor":"c0302a","gemas":150}],"materiais":[{"material":"lingote_ferro","quantidade":5,"gemas":20,"limite_dia":3},{"material":"lingote_aco","quantidade":2,"gemas":30,"limite_dia":2},{"material":"couro","quantidade":3,"gemas":15,"limite_dia":3},{"material":"tecido_nobre","quantidade":1,"gemas":40,"limite_dia":1},{"material":"fragmentos","quantidade":10,"gemas":25,"limite_dia":3}],"ofertas":[{"id":"oferta_revanche","gatilho":"derrota_por_pouco","conteudo":{"gemas":100,"bau":"ferro"},"preco":"R$ 4,90","duracao_s":3600,"intervalo_s":86400},{"id":"oferta_nova_liga","gatilho":"subiu_liga","conteudo":{"gemas":300,"bau":"ouro"},"preco":"R$ 14,90","duracao_s":7200,"intervalo_s":86400},{"id":"oferta_forja","gatilho":"projeto_sem_material","conteudo":{"lingote_ferro":10,"lingote_aco":3,"couro":4},"preco":"R$ 9,90","duracao_s":3600,"intervalo_s":86400}],"derrota_por_pouco_pontos":1,"gemas_por_hora_timer":10}$json$::jsonb, true, true),
	('metas', 1, $json${"versao":1,"_nota":"Renome, missoes, login, conquistas e titulos (GDD O que acrescentar; Pacote 3.21). O dia vira as virada_hora_utc horas UTC (3 = meia-noite de Brasilia); a semana comeca na segunda. Eventos contados pelo servico: justa, vitoria (disputa do PvE vencida, manual ou automatica), tres_estrelas, derrubada, torneio_vencido, regiao_vencida, sequencia (melhor sequencia de vitorias), bau_aberto, peca_nova, treino, forja, melhoria_peca, melhoria_10, predio. Recompensa: ouro, fragmentos, chaves, bau (tipo), xp. Renome: soma por evento; as faixas definem a torcida (pulo da arquibancada e flamulas) e os convites (torneios com renome_minimo em pve.json).","virada_hora_utc":3,"renome":{"ganho":{"vitoria":4,"tres_estrelas":2,"derrubada":3,"campeao":25,"regiao_vencida":60},"faixas":[{"nome":"desconhecido","minimo":0,"torcida":1},{"nome":"promissor","minimo":100,"torcida":2},{"nome":"conhecido","minimo":300,"torcida":3},{"nome":"famoso","minimo":800,"torcida":4},{"nome":"lendario","minimo":2000,"torcida":5}],"torcida":{"pulo_px_por_nivel":2,"pulos":3,"flamulas_por_nivel":10}},"missoes":{"diarias_por_dia":3,"semanais_por_semana":2,"diarias":[{"id":"vencer_3","evento":"vitoria","meta":3,"recompensa":{"ouro":25}},{"id":"justar_5","evento":"justa","meta":5,"recompensa":{"ouro":15,"fragmentos":1}},{"id":"derrubar_1","evento":"derrubada","meta":1,"recompensa":{"fragmentos":2}},{"id":"treinar_2","evento":"treino","meta":2,"recompensa":{"ouro":20}},{"id":"abrir_bau_1","evento":"bau_aberto","meta":1,"recompensa":{"ouro":20}},{"id":"tres_estrelas_1","evento":"tres_estrelas","meta":1,"recompensa":{"ouro":15,"fragmentos":1}},{"id":"melhorar_1","evento":"melhoria_peca","meta":1,"recompensa":{"fragmentos":2}}],"semanais":[{"id":"vencer_20","evento":"vitoria","meta":20,"recompensa":{"chaves":1}},{"id":"derrubar_8","evento":"derrubada","meta":8,"recompensa":{"bau":"ferro"}},{"id":"torneios_2","evento":"torneio_vencido","meta":2,"recompensa":{"bau":"ouro"}},{"id":"forjar_1","evento":"forja","meta":1,"recompensa":{"chaves":1}}]},"login":[{"ouro":50},{"fragmentos":5},{"bau":"madeira"},{"ouro":100},{"chaves":1},{"bau":"ferro"},{"bau":"ouro"}],"conquistas":[{"id":"primeira_vitoria","evento":"vitoria","meta":1,"recompensa":{"ouro":30}},{"id":"cem_justas","evento":"justa","meta":100,"recompensa":{"chaves":1},"titulo":"veterano_da_lica"},{"id":"derrubador","evento":"derrubada","meta":25,"recompensa":{"fragmentos":10},"titulo":"derruba_cavaleiros"},{"id":"inquebravel","evento":"sequencia","meta":10,"recompensa":{"bau":"ouro"},"titulo":"o_inquebravel"},{"id":"campeao_das_feiras","evento":"regiao_vencida","meta":1,"recompensa":{"ouro":100},"titulo":"campeao_das_feiras"},{"id":"senhor_do_reino","evento":"regiao_vencida","meta":4,"recompensa":{"bau":"real"},"titulo":"senhor_do_reino"},{"id":"grande_campeao","evento":"regiao_vencida","meta":5,"recompensa":{"bau":"real"},"titulo":"o_grande_campeao"},{"id":"colecionador","evento":"peca_nova","meta":20,"recompensa":{"fragmentos":15},"titulo":"o_colecionador"},{"id":"mestre_da_forja","evento":"melhoria_10","meta":1,"recompensa":{"chaves":1},"titulo":"mestre_da_forja"},{"id":"forjador","evento":"forja","meta":10,"recompensa":{"fragmentos":10}}]}$json$::jsonb, true, true),
	('mira', 1, $json${"versao":3,"_nota":"Zonas em px do quadro 160x160 do cavaleiro (origem no chao entre as patas, x para a frente, y para cima negativo), retangulos [x, y, largura, altura]. Ordem de prioridade: a primeira zona que contem o ponto vence. Precisao aumenta so as zonas que pontuam; o cavalo (falta) nao cresce. Precisa bater com a arte (cavaleiro.tscn). v2 (3.16): o crescimento pela precisao tem teto suave (joelho_pct do maximo passa inteiro; acima, cada ponto rende menos). GDD: acerto ate o teto, perto dele cada ponto rende menos. v3 (2026-10-15): zonas medidas na arte do PixelLab (tools/gerar_personagem.py): escudo pequeno no ombro cobre a metade de tras do peito; a frente e a parte de baixo do tronco ficam expostas.","zonas":[{"nome":"escudo","retangulos":[[-3,-113,16,22]],"cresce":true},{"nome":"capacete","retangulos":[[2,-140,20,24]],"cresce":true},{"nome":"peito","retangulos":[[-3,-114,24,34]],"cresce":true},{"nome":"cavalo","retangulos":[[-55,-88,105,40],[45,-104,33,36],[-72,-85,17,30]],"cresce":false}],"precisao":{"crescimento_por_ponto_milesimos":400,"crescimento_max_pct":50,"joelho_pct":70},"ponta_inicial":[40,-165],"limites_ponta":[-90,-200,180,200],"oscilacao":{"amplitude_px":3,"frequencia_x_milesimos":1300,"frequencia_y_milesimos":1700}}$json$::jsonb, true, true),
	('nomes_proibidos', 1, $json${"versao":1,"_nota":"Raizes proibidas em nomes de cavaleiro e casa (pt e en). A comparacao e feita sem acento, em minusculas, trocando numeros/simbolos comuns por letras (0->o, 1->i, 3->e, 4->a, 5->s, 7->t, @->a, $->s) e sem espacos. Acrescente raizes aqui; nao precisa mexer no codigo.","tamanho_min":2,"tamanho_max":20,"raizes":["porra","caralh","buceta","boceta","puta","putinh","viad","bicha","cuzao","arrombad","fdp","foder","fodid","merda","piroca","rola","xoxota","xereca","otario","vagabund","corno","macac","nazi","hitler","estupr","pedofil","fuck","shit","bitch","cunt","dick","pussy","nigg","fag","whore","slut","rape","retard","bastard","asshole"]}$json$::jsonb, true, false),
	('nomes_sorteio', 1, $json${"versao":1,"_nota":"Nomes para o botao de sortear da criacao de personagem (nomes proprios, iguais em todas as linguas).","femininos":["Isolda","Beatriz","Leonor","Matilde","Urraca","Inês","Brites","Teresa","Mafalda","Constança","Aldonça","Branca"],"masculinos":["Afonso","Rodrigo","Gonçalo","Mem","Egas","Martim","Nuno","Fernão","Vasco","Pero","Godofredo","Tristão"],"casas":["Casa de Valcorvo","Casa Ferreira","Casa de Montenegro","Casa Lobato","Casa de Altaroca","Casa Pardal","Casa de Ribanegra","Casa Torralva","Casa de Pedra Alta","Casa Vilarinho"]}$json$::jsonb, true, true),
	('ordem', 1, $json${"versao":1,"_nota":"Ordens (guildas), ajuda, doacoes, torneio semanal, loja da ordem, chat e amigos (GDD, Funcoes sociais; Pacote 3.20). Ate o servidor (3.8) tudo isso e SIMULADO no aparelho: ordens, membros, pedidos, chat e rivais do torneio saem da semente do save e a tela avisa. Os numeros daqui sao a base do que a Edge Function vai ler.","membros_max":30,"nivel_minimo":5,"criar":{"ouro":300,"recrutas":3},"nome":{"min":3,"max":20},"cargos":["lider","oficial","membro"],"permissoes":{"lider":["promover","rebaixar","expulsar_oficial","expulsar_membro","editar_brasao","editar_nome","passar_lideranca","dissolver"],"oficial":["expulsar_membro","editar_brasao"],"membro":[]},"simuladas":{"quantas":5,"membros":[6,24],"poder":[30,70]},"ajuda":{"segundos_por_ajuda":300,"ajudas_max_por_pedido":4,"moeda_por_ajuda":2,"moeda_max_dia":30,"resposta_s":[20,120],"pedidos_simulados":3,"balde_s":1800,"tipos":["treino_cavaleiro","treino_cavalo","forja","fundicao","melhoria"]},"doacao":{"limite_dia_unidades":15,"moeda_por_doacao":1,"pedidos_simulados":3,"materiais":{"sucata":[3,8],"couro":[1,3],"lingote_ferro":[1,3]}},"torneio":{"ordens_simuladas":7,"vitorias_por_membro_semana":[1,6],"vitorias_do_jogador_max":40,"premios":[{"ate_posicao":1,"moeda":60,"bau":"ouro"},{"ate_posicao":3,"moeda":40,"bau":"ferro"},{"ate_posicao":5,"moeda":25},{"ate_posicao":99,"moeda":10}]},"loja":{"_nota":"Moeda da ordem so compra projetos e materiais (nada de gemas). limite_semana = quantas vezes por semana.","itens":[{"id":"lingote_aco","moeda":30,"limite_semana":3,"conteudo":{"lingote_aco":2}},{"id":"couro","moeda":15,"limite_semana":4,"conteudo":{"couro":3}},{"id":"tecido_nobre","moeda":40,"limite_semana":2,"conteudo":{"tecido_nobre":2}},{"id":"fragmentos","moeda":20,"limite_semana":5,"conteudo":{"fragmentos":10}},{"id":"projeto_cavaleiro_andante","moeda":400,"limite_semana":1,"projeto":"cavaleiro_andante"}]},"chat":{"mensagens_max":40,"texto_max":120,"intervalo_envio_s":2,"simulado_intervalo_s":150,"simulado_por_abertura_max":4,"motivos_denuncia":["ofensa","spam","outro"],"denuncias_max":50},"amigos":{"max":50,"pool_simulado":40},"praca_max":3}$json$::jsonb, true, true),
	('padrao', 1, $json${"versao":2,"_nota":"Lado usado enquanto nao existem dados do jogador (2.4) e para o rival sem perfil: atributos (0 a 100), equipamento inicial e habilidade.","cavaleiro":{"forca":50,"precisao":50,"equilibrio":50},"cavalo":{"velocidade":50,"folego":50,"temperamento":50},"equipamento":{"elmo":{"defesa":8,"durabilidade":60},"peitoral":{"defesa":8,"durabilidade":60},"escudo":{"defesa":5,"bloqueio_milesimos":40,"durabilidade":60},"lanca":{"poder":5,"precisao":0,"durabilidade":40}},"habilidade":"investida"}$json$::jsonb, true, true),
	('paletas', 1, $json${"versao":1,"_nota":"Cores da casa e materiais do personagem (aparencia, nao balanceamento). Os nomes viram chaves de traducao COR_<NOME> quando aparecerem na tela.","cores_casa":{"azul_real":"2c3a5a","vermelho_sangue":"7a2326","verde_floresta":"2f4a2c","ouro_velho":"b08a3a","prata":"9aa0a6","preto_carvao":"26221f","purpura":"4a2a4f","branco_osso":"d8d0bf"},"tinturas":{"_nota":"Regra das tinturas da heraldica: nunca metal sobre metal nem cor sobre cor. Os sorteios (criacao e brasao) juntam sempre um metal com uma cor, o que da contraste e combina. Toda cor de cores_casa esta em uma das listas.","metais":["ouro_velho","prata","branco_osso"],"cores":["azul_real","vermelho_sangue","verde_floresta","preto_carvao","purpura"]},"mundo":{"_nota":"Cores do cenario (vila, arena, retratos) mandadas ao PixelLab junto com as demais como paleta forcada (tools/gerar_arte.py): tudo sai do mesmo conjunto de cores.","pedra":"6e6a63","pedra_clara":"9b958a","lama":"4a3b2c","terra":"6b5640","capim":"4f5a35","musgo":"3c4630","palha":"a08a55","ardosia":"3d4250","ceu_nublado":"8c9196","sombra":"1c1a1d","fogo":"c86a2a"},"metais":{"ferro":"8a8f96","aco_escuro":"4b5058","latao":"a8874a"},"neutros":{"couro":"6b4a33","madeira":"8a6a45","tecido_cru":"9a8c74"},"peles":{"clara":"e0b89a","media":"c08c66","morena":"8f5f40","escura":"5c3a28","palida":"e8cfc0"},"cabelos":{"preto":"1e1a18","castanho":"4a3020","ruivo":"7a3a1c","loiro":"b8955a","grisalho":"8a8680","branco":"d0ccc4"},"pelagens":["alazao","preto","branco"],"casa_padrao":{"principal":"azul_real","secundaria":"ouro_velho","metal":"ferro","neutro":"couro","pele":"media","cabelo":"castanho"}}$json$::jsonb, true, true),
	('progressao', 1, $json${"versao":1,"_nota":"XP acumulado para chegar a cada nivel do cavaleiro (indice 0 = nivel 1). O nivel libera predios da vila (vila.json) e torneios (pve.json). A curva fina sai da simulacao de economia (3.12).","xp_por_nivel":[0,50,160,340,600,950,1400,1950,2600,3400,4300,5300,6400,7600,8900,10300,11800,13400,15100,16900,18800],"habilidades":{"_nota":"GDD: 1 espaco no comeco; o segundo libera numa liga alta (ou no nivel, enquanto nao ha liga). No maximo uma por grupo (ofensiva, defensiva). base = as que todo cavaleiro conhece; as de conjunto exigem o conjunto completo equipado.","base":["investida","bloqueio","golpe_pesado"],"espacos_iniciais":1,"segundo_espaco_liga":"platina","segundo_espaco_nivel":15}}$json$::jsonb, true, true),
	('pve', 1, $json${"versao":2,"_nota":"Circuito PvE (GDD Disputas PvE). Regiao = torneios em ordem; torneio = chave de rivais enfrentados em sequencia (perder repete a mesma disputa). Estrelas por disputa: 1 vitoria, +1 sem errar (nenhum golpe do jogador em erro ou falta), +1 vitoria por derrubada. Com 3 estrelas a disputa pode ser repetida no automatico, exceto campeao e a primeira luta (sempre manuais). O automatico joga pelo jogador com o perfil de IA perfil_automatico. Recompensas: por disputa (manual e automatico; o manual paga mais) e por torneio (na primeira vez que fecha). Rivais: perfil da IA, atributos, equipamento (modelos de itens.json), habilidade, cores e brasao. v2 (3.13): ordem_regioes; cada regiao tem torneios em ordem, nemesis, recompensa_pct (multiplica a recompensa por disputa) e recompensa_regiao (projeto ao vencer o ultimo torneio obrigatorio, que libera a proxima regiao). Torneio: opcional (nao bloqueia a regiao) e desafios (ids de desafios, aplicados pela regra antes da justa). Rival: campeao (sempre manual), provocacao (texto que o arauto le), perfil_ajuste (soma ao perfil da IA: estilo de mira), por_regiao (substitui atributos/equipamento naquela regiao; o nemesis usa). 3.15: materiais_vitoria (materiais por vitoria; no automatico, recompensa_automatico_pct) e recompensa_regiao.materiais (ornamento do campeao da regiao). 3.21: renome_minimo = convite (o torneio so abre com esse renome; metas.json).","perfil_automatico":"equilibrado","recompensa_automatico_pct":60,"regioes":{"feiras":{"torneios":["feira_moinho","feira_ponte","feira_mercado","feira_colheita","feira_grande"],"nemesis":"nemesis_corvo","recompensa_pct":100,"recompensa_regiao":{"projeto":"vigia","materiais":{"ornamento":1}},"materiais_vitoria":{"sucata":2}},"condado":{"torneios":["torneio_vale_verde","torneio_ponte_velha","desafio_ribeira","torneio_castelo_alvar","torneio_feira_conde","torneio_conde"],"nemesis":"nemesis_corvo","recompensa_pct":160,"recompensa_regiao":{"projeto":"