	('sensacao', 1, $json${"versao":1,"_nota":"Intensidades da sensacao de impacto (apresentacao, nao regra). forca vai de 0 a 1: dano / dano_referencia, e 1 na derrubada. Tempos em ms.","dano_referencia":25,"hit_stop":{"ms_min":40,"ms_max":140,"escala_tempo":0.05},"tremor":{"trauma_min":0.25,"trauma_max":0.8,"trauma_derrubada":1.0},"lascas":{"quantidade_min":6,"quantidade_max":18},"faiscas":{"quantidade_min":4,"quantidade_max":14,"zonas":["capacete","peito"]},"peca_voando":{"dano_minimo":18,"distancia_px":60,"altura_px":50,"duracao_ms":700},"vibracao":{"ms_min":30,"ms_max":120},"queda":{"duracao_ms":650,"giro_graus":80,"distancia_px":34},"lanca_quebrada_escala":0.45,"habilidade":{"_nota":"Efeito visual das habilidades (3.16): ativa = brilho e rastro no cavaleiro; passiva = escudo pisca.","cor_brilho":"fff0a0","brilho_s":0.6,"cor_rastro":"ffe08acc","rastro_s":0.5,"rastro_quantidade":24,"cor_escudo":"9fd4ff","escudo_piscadas":4}}$json$::jsonb, true, true),
	('servidor', 1, $json${"versao":1,"_nota":"Parametros do SERVIDOR (Edge Functions, Parte 3): limites de chamadas, idempotencia e conferencia da justa. So a secao cliente e lida pelo jogo; fica na tabela de balanceamento remoto (3.3) para mudar sem lancar versao.","limites":{"acoes_por_minuto":60,"chat_por_minuto":20,"tentativas_conflito":3,"idempotencia_dias":7,"cooldown_disputa_s":30,"denuncias_para_silenciar":5,"silenciar_horas":24},"temporadas":{"_nota":"Grade global das temporadas (mesma para todos): epoca = uma segunda-feira 00:00 UTC; a duracao e economia.ligas.temporada_dias.","epoca":1791763200},"anticheat":{"toque_min_intervalo_ms":40,"reacao_largada_min_ms":60,"entradas_max":400},"cliente":{"_nota":"Lido pelo jogo (arena): como gravar as entradas da justa que o servidor confere. A mira so muda o golpe pelo ultimo ponto, entao basta um ponto a cada registro_mira_ms (e o ultimo antes de soltar ou do choque).","registro_mira_ms":150},"argumentos":{"texto_max":200,"lista_max":50,"profundidade_max":4}}$json$::jsonb, true, false),
